use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored, tried in order.
const KEYS: &[&str] = &["urls", "subscriptions", "feeds"];

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let mut chars = s.trim().chars().peekable();
    if chars.next()? != '[' {
        return None;
    }
    let mut out = Vec::new();
    loop {
        while matches!(chars.peek(), Some(c) if c.is_whitespace()) {
            chars.next();
        }
        match chars.next()? {
            ']' => break,
            ',' => continue,
            '"' => {
                let mut cur = String::new();
                loop {
                    match chars.next()? {
                        '"' => break,
                        '\\' => match chars.next()? {
                            'n' => cur.push('\n'),
                            't' => cur.push('\t'),
                            'r' => cur.push('\r'),
                            'b' => cur.push('\u{8}'),
                            'f' => cur.push('\u{c}'),
                            'u' => {
                                let mut code = 0u32;
                                for _ in 0..4 {
                                    code = code * 16 + chars.next()?.to_digit(16)?;
                                }
                                cur.push(char::from_u32(code).unwrap_or('\u{fffd}'));
                            }
                            other => cur.push(other),
                        },
                        c => cur.push(c),
                    }
                }
                out.push(cur);
            }
            _ => return None,
        }
    }
    Some(out)
}

/// Parse plain text: one URL per line (or separated by commas/whitespace),
/// with `#` starting a comment.
fn parse_plain(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in s.lines() {
        let line = match line.find('#') {
            Some(i) if i == 0 || line[..i].ends_with(char::is_whitespace) => &line[..i],
            _ => line,
        };
        for tok in line.split(|c: char| c == ',' || c.is_whitespace()) {
            let tok = tok.trim();
            if !tok.is_empty() {
                out.push(tok.to_string());
            }
        }
    }
    out
}

fn parse(s: &str) -> Vec<String> {
    let raw = match parse_json_string_array(s) {
        Some(v) => v,
        None => parse_plain(s),
    };
    let mut out: Vec<String> = Vec::new();
    for u in raw {
        let u = u.trim().to_string();
        if !u.is_empty() && !out.contains(&u) {
            out.push(u);
        }
    }
    out
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(value) = state_read::get(key) {
                let urls = parse(&value);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        SubscriptionList { urls: Vec::new() }
    }
}

export!(Node);
